<?php declare(strict_types=1);$base=config('app.base_path');$trash=!empty($trash); ?><div class="page-header"><div><h1><?= $trash?'Deleted Destinations':'Tourism Destinations' ?></h1><p>Platform-managed places that can later connect stays, tours, restaurants and transport.</p></div><div class="page-actions"><?php if($trash): ?><a class="btn btn-secondary" href="<?= $base ?>/tourism/destinations">Active Destinations</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/tourism/destinations?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/tourism/destinations/create">Add Destination</a><?php endif; ?></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>Destination</th><th>Location</th><th>Coordinates</th><th>Stays</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(empty($destinations)): ?><tr><td colspan="6"><div class="empty-state">No destinations found.</div></td></tr><?php else:foreach($destinations as $d): ?><tr><td><strong><?= htmlspecialchars((string)$d['name'],ENT_QUOTES,'UTF-8') ?></strong><br><small><?= htmlspecialchars((string)($d['best_time_to_visit']??''),ENT_QUOTES,'UTF-8') ?></small></td><td><?= htmlspecialchars(trim((string)($d['city']??'').' / '.(string)($d['district']??''),' /'),ENT_QUOTES,'UTF-8') ?></td><td><?= $d['latitude']!==null?htmlspecialchars($d['latitude'].' , '.$d['longitude'],ENT_QUOTES,'UTF-8'):'Not set' ?></td><td><?= (int)$d['stay_count'] ?></td><td><?= htmlspecialchars((string)$d['status'],ENT_QUOTES,'UTF-8') ?></td><td><?php if($trash): ?><form method="post" action="<?= $base ?>/tourism/destinations/<?= (int)$d['id'] ?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/tourism/destinations/<?= (int)$d['id'] ?>">View</a> <a class="link-button" href="<?= $base ?>/tourism/destinations/<?= (int)$d['id'] ?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach;endif;?></tbody></table></div>
